def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find each existing horizontal color sequence; these are the templates.
    templates = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start > 1:
                templates.append(row[start:c])

    # Expand isolated colored cells, aligning their color with its position
    # in the matching template. Clip the template at the grid edges.
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if not value:
                continue
            if any(grid[r][x] != 0 for x in range(max(0, c-1), min(w, c+2)) if x != c):
                continue
            template = next((t for t in templates if value in t), None)
            if template is None:
                continue
            left = c - template.index(value)
            for i, color in enumerate(template):
                x = left + i
                if 0 <= x < w:
                    g[r][x] = color
    return g
